-- store/_retired/deDE.lua
-- German translations for phrases no addon in the family currently uses.
--
-- NOT dead. A phrase lands here when the last addon using it drops or rewords it,
-- and scan.py moves it straight back into store/deDE.lua the moment any addon
-- starts using that exact English key again. Everything Quests v1.38.0 moved 224
-- phrases to EQ Objective Tracker in one release - this is what stops that costing
-- a translation.
--
-- Nothing here reaches the game. There is no reason to translate anything in this
-- file, and no reason to delete anything from it either.

local L = {}

L["%d hidden entries restored."] = "%d ausgeblendete Einträge wiederhergestellt."
L["%d spells tracked. \"Default\" follows this category's Defaults tab; the last column flags a spell Important or Pinned."] = "%d Zauber werden verfolgt. „Standard“ folgt dem Reiter Standardwerte dieser Kategorie, die letzte Spalte markiert einen Zauber als Wichtig oder Angeheftet."
L["%s  \194\183  %s quests  \194\183  %s  \194\183  %s XP"] = "%s  ·  %s Quests  ·  %s  ·  %s EP"
L["%s Defaults"] = "Standardwerte für %s"
L["%s%s|r %s(%s)|r%s  \226\128\148  %s%d|r in progress  %s%d|r banked  %s%d|r done  %s%d|r left"] = "%s%s|r %s(%s)|r%s  —  %s%d|r laufend  %s%d|r gebunkert  %s%d|r erledigt  %s%d|r offen"
L["/eqs\n/everythingquests\n\n|cff999999Both open this options window.|r\n\n/eqs whatsnew\n\n|cff999999Show what's new in the latest update.|r\n\n/eqs session\n\n|cff999999Show a recap of your current play session.|r"] = "/eqs\n/everythingquests\n\n|cff999999Beide öffnen dieses Optionsfenster.|r\n\n/eqs whatsnew\n\n|cff999999Zeigt die Neuerungen des letzten Updates.|r\n\n/eqs session\n\n|cff999999Zeigt eine Zusammenfassung deiner aktuellen Spielsitzung.|r"
L["[Done] %s - completed"] = "[Erledigt] %s - abgeschlossen"
L["[Done] Fangs for the Memories complete \226\128\148 Corrosive Victory earned."] = "[Erledigt] Fangs for the Memories abgeschlossen — Corrosive Victory erhalten."
L["[Done] Gilded Stash earned! (%d / %d)"] = "[Erledigt] Vergoldetes Versteck erhalten! (%d / %d)"
L["[Done] SA: %s"] = "[Erledigt] SA: %s"
L["A finished quest's title takes the title color instead of green, and so do its finished objectives unless a Finished Objective Color is picked. Only Class color, Custom color and Original Style give a title color."] = "Der Titel einer abgeschlossenen Quest erhält statt Grün die Titelfarbe, ebenso ihre erfüllten Ziele, es sei denn, unter „Farbe erfüllter Ziele“ ist eine Farbe gewählt. Eine Titelfarbe geben nur „Klassenfarbe“, „Eigene Farbe“ und „Originalstil“."
L["A small funnel at the top-left of the tracker that opens a list of the filters, so you can turn quest types and the current-zone filter on and off in a couple of clicks. The list stays open while you tick boxes, and the funnel turns gold while any filter is hiding quests. It changes the same filters as the Filters card. Off by default."] = "Ein kleiner Trichter oben links im Tracker, der eine Liste der Filter öffnet, sodass du Questarten und den Filter für das aktuelle Gebiet mit ein paar Klicks ein- und ausschalten kannst. Die Liste bleibt offen, während du Kästchen anhakst, und der Trichter wird golden, solange ein Filter Quests ausblendet. Er ändert dieselben Filter wie der Bereich „Filter“. Standardmäßig deaktiviert."
L["A unified replacement for the Blizzard quest experience: a custom tracker, objective markers on the map and minimap, nameplate quest icons, and a browser for the quests you have not picked up yet."] = "Ein einheitlicher Ersatz für das Questerlebnis von Blizzard: ein eigener Tracker, Zielmarkierungen auf Welt- und Minikarte, Questsymbole auf Namensplaketten und ein Browser für Quests, die du noch nicht angenommen hast."
L["A unified replacement for the Blizzard quest experience: a custom tracker, world-map overlays, quest history, and a Midnight chain guide."] = "Ein einheitlicher Ersatz für das Questerlebnis von Blizzard: ein eigener Tracker, Weltkartenüberlagerungen, ein Questverlauf und ein Questreihenführer für Midnight."
L["Account-wide alt overview"] = "Accountweite Twink-Übersicht"
L["Account-wide quest rewards. Totals count only quests turned in while reward tracking was on; older entries didn't capture XP or gold."] = "Accountweite Questbelohnungen. Die Summen zählen nur Quests, die bei aktiver Belohnungsaufzeichnung abgegeben wurden. Ältere Einträge haben weder EP noch Gold erfasst."
L["Adds the quest log heading each quest came from as a small line under its title."] = "Fügt unter dem Titel jeder Quest die Überschrift aus dem Questlog als kleine Zeile hinzu."
L["Adds the quest log heading each quest came from as a small line under its title. Not shown while Show zone headers is on, on the Appearance tab."] = "Fügt unter dem Titel jeder Quest die Überschrift aus dem Questlog als kleine Zeile hinzu. Wird nicht angezeigt, solange „Gebietsüberschriften anzeigen“ im Reiter „Darstellung“ aktiviert ist."
L["Also reads the progress other quest addons broadcast, so you see everyone in the group rather than only the people running EQ. When you join a group EQ asks those addons for their quest logs, the same way they ask each other. Your own progress is never sent on their channel."] = "Liest auch den Fortschritt, den andere Quest-Addons senden, damit du alle in der Gruppe siehst und nicht nur die Leute mit EQ. Wenn du einer Gruppe beitrittst, fragt EQ diese Addons nach ihren Questlogs, so wie sie sich auch gegenseitig fragen. Dein eigener Fortschritt wird nie über ihren Kanal gesendet."
L["An on-screen panel while inside a delve showing the story variant and its grade, the recommended curios for your role, your run timer, and your death count."] = "Ein Bildschirmpanel in einer Tiefe, das die Geschichtsvariante und ihre Wertung, die empfohlenen Kuriositäten für deine Rolle, deinen Laufzeit-Timer und deine Todeszahl zeigt."
L["Applies to spells flagged Important in the Filters tab. Important spells use the hold and sound below instead of the normal ones."] = "Gilt für Zauber, die im Reiter Filter als Wichtig markiert sind. Wichtige Zauber verwenden die Haltedauer und den Ton unten statt der normalen."
L["Bars 1"] = "Leisten 1"
L["Bars 2"] = "Leisten 2"
L["Bars 3"] = "Leisten 3"
L["Better questing for Classic: objective markers on the world map and minimap, every quest giver with something for you, a browser for almost any quest you have not picked up yet, and quest progress on tooltips and nameplates."] = "Besseres Questen für Classic: Zielmarkierungen auf Welt- und Minikarte, jeder Questgeber, der etwas für dich hat, ein Browser für fast jede Quest, die du noch nicht angenommen hast, und Questfortschritt in Tooltips und auf Namensplaketten."
L["Better questing for WoW Forever: objective markers on the world map and minimap, every quest giver with something for you, a guide to the quest chains, a browser for almost any quest you have not picked up yet, and quest progress on tooltips and nameplates."] = "Besseres Questen für WoW Forever: Zielmarkierungen auf Welt- und Minikarte, jeder Questgeber, der etwas für dich hat, ein Führer durch die Questreihen, ein Browser für fast jede Quest, die du noch nicht angenommen hast, und Questfortschritt in Tooltips und auf Namensplaketten."
